effect.shader:

    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord.xy

   /////////////////////////

        float Hash( vec2 p)
        {
        	vec3 p2 = vec3(p.xy,deltad);
            return fract(sin(dot(p2,vec3(37.1,61.7, 12.4)))*3758.5453123);
        }

        float noise(in vec2 p)
        {
            vec2 i = floor(p);
        	vec2 f = fract(p);
        	f *= f * (3.0-2.0*f);

            return mix(mix(Hash(i + vec2(0.,0.)), Hash(i + vec2(1.,0.)),f.x),
        		mix(Hash(i + vec2(0.,1.)), Hash(i + vec2(1.,1.)),f.x),
        		f.y);
        }

        float fbm(vec2 p) 
        {
        	float v = 0.0;
        	v += noise(p*1.)*.5;
        	v += noise(p*2.)*.25;
        	v += noise(p*4.)*.125;
        	return v;
        }

   /////////////////////////
    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);

        vec2 TanRyu;
        TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        TanRyu.y*=acLayerSize.y/acLayerSize.x;

        TanRyu /= scale;
        TanRyu *= rot2m((70.0+angle)*0.0174533);
        TanRyu += vec2((520.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;

        vec2 scaleVec;
        scaleVec = vec2(scale*stretch.x,scale*stretch.y);
        TanRyu /= scaleVec;

        /////////////////////////

    	vec4 fragColor;

                vec2 uv = TanRyu;

        	vec3 src = texture2DCv(inputImg.texture, acScreenNorm).rgb;

        	vec4 tgt = vec4(colorbg.rgb, 0.0);

        	vec4 col = vec4(src, 1.0);

        	float ctime = mod(progressa*.5,2.5);

        	float d = uv.x+uv.y*0.5 + deltab*fbm(uv*deltac) + ctime*1.3;
        	if (d >0.35) col.rgb = clamp(col.rgb-(d-0.35)*10.,0.0,1.0);
        	if (d >0.47) {
        	if (d < 0.5 ) col.rgb += (d-0.4)*33.0*0.5*(0.0+noise(100.*uv+vec2(-ctime*2.,0.)))*vec3(color.rgb);
        	else col += tgt; }

        	fragColor = col * texColor.a;

         	gl_FragColor = mix(texColor, fragColor, alpha);


    }
